def sheet(cells: dict[str, str]) -> dict[str, int | str]:
    cache: dict[str, int | str] = {}
    formulas: dict[str, str] = {}
    row_cells: list[list[tuple[int, str]]] = [[] for _ in range(100)]

    for cname, content in cells.items():
        r = int(cname[1:])
        c = ord(cname[0]) - 65
        row_cells[r].append((c, cname))
        s = content.strip()
        if s[0] == "=":
            formulas[cname] = s
        else:
            cache[cname] = int(s)

    for r in range(1, 100):
        if len(row_cells[r]) > 1:
            row_cells[r].sort()

    def iter_range(r1: int, c1: int, r2: int, c2: int):
        for r in range(r1, r2 + 1):
            for c, cname in row_cells[r]:
                if c < c1:
                    continue
                if c > c2:
                    break
                yield cname

    def tokenize(s: str) -> list[tuple[str, int | str]]:
        tokens: list[tuple[str, int | str]] = []
        i = 1
        n = len(s)
        while i < n:
            ch = s[i]
            if ch.isspace():
                i += 1
            elif "0" <= ch <= "9":
                j = i + 1
                while j < n and "0" <= s[j] <= "9":
                    j += 1
                tokens.append(("NUM", int(s[i:j])))
                i = j
            elif "A" <= ch <= "Z":
                j = i + 1
                while j < n and ("A" <= s[j] <= "Z" or "0" <= s[j] <= "9"):
                    j += 1
                word = s[i:j]
                if word in ("SUM", "MIN", "MAX", "IF"):
                    tokens.append(("FUNC", word))
                else:
                    tokens.append(("CELL", word))
                i = j
            elif ch == "<":
                if i + 1 < n and s[i + 1] == "=":
                    tokens.append(("OP", "<="))
                    i += 2
                elif i + 1 < n and s[i + 1] == ">":
                    tokens.append(("OP", "<>"))
                    i += 2
                else:
                    tokens.append(("OP", "<"))
                    i += 1
            elif ch == ">":
                if i + 1 < n and s[i + 1] == "=":
                    tokens.append(("OP", ">="))
                    i += 2
                else:
                    tokens.append(("OP", ">"))
                    i += 1
            elif ch == "=":
                tokens.append(("OP", "="))
                i += 1
            else:
                tokens.append((ch, ch))
                i += 1
        tokens.append(("EOF", ""))
        return tokens

    def parse_formula(s: str):
        tokens = tokenize(s)
        pos = 0

        def parse_expr():
            nonlocal pos
            node = parse_term()
            while tokens[pos][0] in ("+", "-"):
                op = tokens[pos][0]
                pos += 1
                right = parse_term()
                node = ("BIN", op, node, right)
            return node

        def parse_term():
            nonlocal pos
            node = parse_unary()
            while tokens[pos][0] in ("*", "/"):
                op = tokens[pos][0]
                pos += 1
                right = parse_unary()
                node = ("BIN", op, node, right)
            return node

        def parse_unary():
            nonlocal pos
            neg = False
            while tokens[pos][0] == "-":
                pos += 1
                neg = not neg
            node = parse_atom()
            if neg:
                return ("NEG", node)
            return node

        def parse_atom():
            nonlocal pos
            tok_type, tok_val = tokens[pos]
            if tok_type == "NUM":
                pos += 1
                return ("NUM", tok_val)
            if tok_type == "CELL":
                pos += 1
                return ("CELL", tok_val)
            if tok_type == "(":
                pos += 1
                node = parse_expr()
                pos += 1
                return node
            func = tok_val
            pos += 2
            if func == "IF":
                left = parse_expr()
                op = tokens[pos][1]
                pos += 1
                right = parse_expr()
                pos += 1
                then_e = parse_expr()
                pos += 1
                else_e = parse_expr()
                pos += 1
                return ("IF", op, left, right, then_e, else_e)
            args = []
            while True:
                if tokens[pos][0] == "CELL" and tokens[pos + 1][0] == ":":
                    c1_name = tokens[pos][1]
                    c2_name = tokens[pos + 2][1]
                    pos += 3
                    r1, c1 = int(c1_name[1:]), ord(c1_name[0]) - 65
                    r2, c2 = int(c2_name[1:]), ord(c2_name[0]) - 65
                    if r1 > r2:
                        r1, r2 = r2, r1
                    if c1 > c2:
                        c1, c2 = c2, c1
                    args.append(("RANGE", r1, c1, r2, c2))
                else:
                    args.append(parse_expr())
                if tokens[pos][0] == ",":
                    pos += 1
                else:
                    pos += 1
                    break
            return ("AGG", func, args)

        return parse_expr()

    in_progress: set[str] = set()

    for start_name in cells:
        if start_name in cache:
            continue
        in_progress.add(start_name)
        stack: list[tuple] = [("CELL_DONE", start_name)]
        expr = parse_formula(formulas[start_name])
        val: int | str = 0

        while True:
            if expr is not None:
                tag = expr[0]
                if tag == "NUM":
                    val = expr[1]
                    expr = None
                elif tag == "CELL":
                    cname = expr[1]
                    if cname in cache:
                        val = cache[cname]
                        expr = None
                    elif cname not in cells:
                        val = 0
                        expr = None
                    elif cname in in_progress:
                        val = "#CYCLE!"
                        expr = None
                    else:
                        in_progress.add(cname)
                        stack.append(("CELL_DONE", cname))
                        expr = parse_formula(formulas[cname])
                elif tag == "NEG":
                    stack.append(("NEG",))
                    expr = expr[1]
                elif tag == "BIN":
                    stack.append(("BIN_L", expr[1], expr[3]))
                    expr = expr[2]
                elif tag == "IF":
                    stack.append(("IF_L", expr[1], expr[3], expr[4], expr[5]))
                    expr = expr[2]
                elif tag == "AGG":
                    func = expr[1]
                    expr = ("AGG_STEP", func, 0 if func == "SUM" else None, expr[2], 0, None)
                elif tag == "AGG_STEP":
                    _, func, acc, args, arg_idx, range_iter = expr
                    while True:
                        if range_iter is not None:
                            cname = next(range_iter, None)
                            if cname is None:
                                range_iter = None
                                continue
                            if cname in cache:
                                v = cache[cname]
                                if type(v) is str:
                                    val = v
                                    expr = None
                                    break
                                if func == "SUM":
                                    acc += v
                                elif func == "MIN":
                                    if acc is None or v < acc:
                                        acc = v
                                else:
                                    if acc is None or v > acc:
                                        acc = v
                                continue
                            if cname in in_progress:
                                val = "#CYCLE!"
                                expr = None
                                break
                            stack.append(("AGG", func, acc, args, arg_idx, range_iter))
                            in_progress.add(cname)
                            stack.append(("CELL_DONE", cname))
                            expr = parse_formula(formulas[cname])
                            break
                        if arg_idx == len(args):
                            val = 0 if acc is None else acc
                            expr = None
                            break
                        arg = args[arg_idx]
                        arg_idx += 1
                        if arg[0] == "RANGE":
                            range_iter = iter_range(arg[1], arg[2], arg[3], arg[4])
                            continue
                        stack.append(("AGG", func, acc, args, arg_idx, None))
                        expr = arg
                        break
            else:
                if not stack:
                    break
                frame = stack.pop()
                ftag = frame[0]
                if ftag == "CELL_DONE":
                    cname = frame[1]
                    in_progress.remove(cname)
                    cache[cname] = val
                elif ftag == "NEG":
                    if type(val) is not str:
                        val = -val
                elif ftag == "BIN_L":
                    if type(val) is not str:
                        stack.append(("BIN_R", frame[1], val))
                        expr = frame[2]
                elif ftag == "BIN_R":
                    if type(val) is not str:
                        op = frame[1]
                        lv = frame[2]
                        if op == "+":
                            val = lv + val
                        elif op == "-":
                            val = lv - val
                        elif op == "*":
                            val = lv * val
                        else:
                            if val == 0:
                                val = "#DIV/0!"
                            else:
                                q = abs(lv) // abs(val)
                                val = -q if (lv < 0) ^ (val < 0) else q
                elif ftag == "IF_L":
                    if type(val) is not str:
                        stack.append(("IF_R", frame[1], val, frame[3], frame[4]))
                        expr = frame[2]
                elif ftag == "IF_R":
                    if type(val) is not str:
                        op = frame[1]
                        lv = frame[2]
                        if op == "=":
                            cond = lv == val
                        elif op == "<>":
                            cond = lv != val
                        elif op == "<":
                            cond = lv < val
                        elif op == "<=":
                            cond = lv <= val
                        elif op == ">":
                            cond = lv > val
                        else:
                            cond = lv >= val
                        expr = frame[3] if cond else frame[4]
                elif ftag == "AGG":
                    if type(val) is not str:
                        _, func, acc, args, arg_idx, range_iter = frame
                        if func == "SUM":
                            acc += val
                        elif func == "MIN":
                            if acc is None or val < acc:
                                acc = val
                        else:
                            if acc is None or val > acc:
                                acc = val
                        expr = ("AGG_STEP", func, acc, args, arg_idx, range_iter)

    return {name: cache[name] for name in cells}
